def conjugate {G : Type*} [Group G] (x : G) (H : Subgroup G) : Subgroup G  := by
  ext a h ha h_in;
  exact ⟨h * conjugate x h_in, H.mul_mem h_in, H.inv_mem h_in⟩

theorem t4 (φ : G →* H) (ψ : H →* K) (S : Subgroup G) :
    map (ψ.comp φ) S = map ψ (S.map φ)  := by
  ext x;
  simp only [mem_map];
  exact ⟨fun ⟨y, y_in, hy⟩ => ⟨φ y, y_in, rfl⟩, fun ⟨y, z, hz, hy⟩ => ⟨z, z_in, by simp [←map_le_map_z_to_map, hy]⟩⟩

lemma conjugate_one (H : Subgroup G) : conjugate 1 H = H  := by
  ext x
  simp [conjugate, H, mul_left_eq_self;

lemma aux_card_eq [Finite G] (h' : Nat.card G = Nat.card H * Nat.card K) :
    Nat.card (G ⧸ H) = Nat.card K   := by
  calc
  _ * Nat.card H = _ := by rw [← H.index_eq_card, H.index_mul_card];
  _ = _ * Nat.card H := by rw [h', mul_comm];
  exact Nat.eq_of_mul_eq_mul_right Nat.card_pos this

def iso₁ [Fintype G] (h : Disjoint H K) (h' : Nat.card G = Nat.card H * Nat.card K) : K ≃* G ⧸ H   := by
  apply MulEquiv.ofBijective ((QuotientGroup.mk' H).restrict K);
  rw [Nat.bijective_iff_injective_and_card],
  constructor;
  simpa [← ker_eq_bot_iff, (QuotientGroup.mk' H).ker_restrict K] using h;
  symm; exact aux_card_eq h'

def iso₂ : G ≃* (G ⧸ K) × (G ⧸ H)   := by
  rw [← ker_eq_bot_iff, card_prod, aux_card_eq h', aux_card_eq (mul_comm (card H) _▸ h'), h'.symm]
  apply MulEquiv.ofBijective (prod_mk (QuotientGroup.mk' K) (QuotientGroup.mk' H))"<;;

 := by
exact MulEquiv.ofBijective ((QuotientGroup.mk' K).prod (QuotientGroup.mk' H)) $ by
rw [Nat.bijective_iff_injective_and_card]; constructor;
· simpa [← ker_eq_bot_iff, ker_prod] using h.symm.eq_bot;
· rw [Nat.card_prod, aux_card_eq h', aux_card_eq (mul_comm (Nat.card H) _▸ h'), h']
